using PetShop_App.Componentes;
using PetShop_App.Dados;
using PetShop_App.Modelos;
namespace PetShop_App.Telas.Pets
{

public partial class PaginaPets : UserControl
{
    public PaginaPets() { InitializeComponent(); if (PetShop_App.Componentes.AmbienteDesign.EstaAtivo(this)) return; Load += async (_, _) => await CarregarAsync(); txtPesquisa.TextChanged += async (_, _) => await CarregarAsync(); btnNovo.Click += async (_, _) => await NovoAsync(); btnEditarRegistro.Click += async (_, _) => await EditarAsync(); btnExcluirRegistro.Click += async (_, _) => await ExcluirAsync(); }
    private async Task CarregarAsync() { if (PetShop_App.Componentes.AmbienteDesign.EstaAtivo(this)) return; try { gradePets.DataSource = (await new RepositorioPetShop().ListarPetsAsync(txtPesquisa.Text)).Select(x => new { x.Id, x.Nome, x.Tutor, x.Especie, x.Raca, x.Porte, Peso = x.Peso + " kg" }).ToList(); if (gradePets.Columns["Id"] is not null) gradePets.Columns["Id"].Visible = false; } catch (Exception ex) { MessageBox.Show(ex.Message, "Não foi possível carregar os pets"); } }
    private async Task NovoAsync() { var repo = new RepositorioPetShop(); var clientes = await repo.ListarClientesAsync(); if (clientes.Count == 0) { MessageBox.Show("Cadastre um cliente antes de cadastrar o pet.", "Vínculo obrigatório"); return; } using var f = new FormularioCadastro("Cadastrar pet", 610); var tutor = f.Combo("Tutor *"); tutor.DataSource = clientes; tutor.DisplayMember = "Nome"; tutor.ValueMember = "Id"; var nome = f.Texto("Nome do pet *"); var especie = f.Combo("Espécie *"); especie.Items.AddRange(["Cão", "Gato", "Ave", "Outro"]); especie.SelectedIndex = 0; var raca = f.Texto("Raça"); var porte = f.Combo("Porte"); porte.Items.AddRange(["Pequeno", "Médio", "Grande"]); porte.SelectedIndex = 0; var nasc = f.Data("Nascimento"); var peso = f.Numero("Peso (kg)", 200, 2); if (f.ShowDialog(this) != DialogResult.OK || tutor.SelectedValue is not int clienteId) return; if (string.IsNullOrWhiteSpace(nome.Text)) { MessageBox.Show("Informe o nome do pet."); return; } await repo.SalvarPetAsync(new Pet { ClienteId = clienteId, Nome = nome.Text.Trim(), Especie = especie.Text, Raca = raca.Text.Trim(), Porte = porte.Text, Nascimento = nasc.Value.Date, Peso = peso.Value }); await CarregarAsync(); }
    private async Task EditarAsync() { if (gradePets.CurrentRow?.Cells["Id"].Value is not int id) return; var repo = new RepositorioPetShop(); var p = (await repo.ListarPetsAsync()).First(x => x.Id == id); var clientes = await repo.ListarClientesAsync(); using var f = new FormularioCadastro("Editar pet", 560); var tutor = f.Combo("Tutor"); tutor.DataSource = clientes; tutor.DisplayMember = "Nome"; tutor.ValueMember = "Id"; tutor.SelectedValue = p.ClienteId; var nome = f.Texto("Nome"); nome.Text = p.Nome; var raca = f.Texto("Raça"); raca.Text = p.Raca; var porte = f.Combo("Porte"); porte.Items.AddRange(["Pequeno", "Médio", "Grande"]); porte.Text = p.Porte; var peso = f.Numero("Peso", 200, 2); peso.Value = p.Peso; if (f.ShowDialog(this) != DialogResult.OK || tutor.SelectedValue is not int clienteId) return; p.ClienteId = clienteId; p.Nome = nome.Text; p.Raca = raca.Text; p.Porte = porte.Text; p.Peso = peso.Value; await repo.AtualizarPetAsync(p); await CarregarAsync(); }
    private async Task ExcluirAsync() { if (gradePets.CurrentRow?.Cells["Id"].Value is not int id || !BotoesCrud.Confirmar("o pet selecionado")) return; try { await new RepositorioPetShop().ExcluirPetAsync(id); await CarregarAsync(); } catch (MySqlConnector.MySqlException) { MessageBox.Show("O pet possui atendimentos vinculados. Remova-os antes."); } }
}

}
